export default () => {
    const mxcad = new McObject()
    mxcad.create({
      canvas: "#myCanvas",
      locateFile: (fileName: string)=> {
            // CDN loading must use resources in wasm/ 2D-ST, because github restrictions cannot use wasm/2d resources
            // Use wasm/2d to comply with the browser same-origin policy or use other means to circumvent the browser same-origin policy
            return self.location.origin + "/mxcad/wasm/2d-st/" + fileName
      },
      // The directory location where the font is loaded
      fontspath: self.location.origin + "/mxcad/fonts",
      // Load the converted drawing file
      fileUrl: self.location.origin + "/mxcad/test.mxweb",
      onOpenFileComplete: ()=>{
            // A construction line extending infinitely in both directions along the 45-degree direction
            const xline = new McDbXline()
            xline.basePoint = new McGePoint3d(0, 0, 0)
            xline.unitDir = new McGeVector3d(1, 1, 0)
            xline.trueColor = new McCmColor(255, 0, 0)
            mxcad.drawEntity(xline)

            // A horizontal construction line along the X-axis direction
            const xline_1 = new McDbXline()
            xline_1.setBasePoint(0, 200, 0)
            xline_1.setUnitDir(1, 0, 0)
            xline_1.trueColor = new McCmColor(0, 255, 0)
            mxcad.drawEntity(xline_1)

            // A vertical construction line along the Y-axis direction
            const xline_2 = new McDbXline()
            xline_2.setBasePoint(200, 0, 0)
            xline_2.setUnitDir(0, 1, 0)
            xline_2.trueColor = new McCmColor(0, 0, 255)
            mxcad.drawEntity(xline_2)

            mxcad.zoomAll()
            mxcad.zoomScale(0.8)
      }
    })
    return (<div style="height: 500px; overflow: hidden;"><canvas id="myCanvas" ></canvas>
    </div>)
}
